def make_a_pile(n):
    """
    Given a positive integer n, create a pile of n levels of stones with these rules:
    - The first level starts with n stones.
    - Each next level increases stones by 2, preserving parity of n (odd/even).
    - Additionally, only levels whose stone counts have a prime number of distinct digits (in decimal)
      are included in the output list.

    Return the list of stones for those filtered levels.

    This extends the original by filtering levels based on a prime count of distinct digits in the stone count.
    """
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                return False
        return True

    def count_distinct_digits(num):
        digits = set(str(num))
        return len(digits) 

    result = []
    for i in range(n):
        stones = n + 2*i
        distinct_digit_count = count_distinct_digits(stones)
        if is_prime(distinct_digit_count):
            result.append(stones)
    return result

