def count_up_to(n):
    """Implement a function that takes a non-negative integer and returns a dictionary where:
    - Keys are prime numbers less than n
    - Values are lists of odd numbers in their Collatz sequence

    For example:
    count_up_to(5) => {2: [1], 3: [1, 5]}
    count_up_to(11) => {2: [1], 3: [1, 5], 5: [1, 5], 7: [1, 11, 17, 13, 5]}
    count_up_to(0) => {}
    count_up_to(1) => {}
    """

    primes_dict = {}

    for i in range(2, n):
        is_prime = True
        for j in range(2, i):
            if i % j == 0:
                is_prime = False
                break

        if is_prime:
            # Generate Collatz sequence for this prime
            collatz = []
            num = i
            while num != 1:
                if num % 2 != 0:
                    collatz.append(num)
                if num % 2 == 0:
                    num = num // 2
                else:
                    num = num * 3 + 1
            collatz.append(1)  # Add 1 which is always the last number
            primes_dict[i] = sorted(list(set(collatz)))  # Remove duplicates and sort

    return primes_dict

