from typing import List, Tuple, Dict, Any
def find_complex_statistics(numbers: List[float]) -> Dict[str, Any]:
    # From a supplied list of numbers (of length at least two), this function calculates a set of complex statistics.
#     It identifies the closest pair of numbers, but instead of returning them directly,
#     it processes their "effective unit digits" in a specific way. It also adds other aggregated statistics.
#     The "effective unit digit" for a float `x` is defined as follows:
#     - If `x` is an integer (e.g., 2.0, -5.0), its effective unit digit is `abs(int(x) % 10)`.
#     - If `x` has a fractional part (e.g., 2.2, -1.48), it's calculated as `abs(int(round(x * 10)) % 10)`.
#       This captures the first digit after the decimal point (e.g., 2.2 -> 2, 1.48 -> 5 (due to rounding 14.8 to 15), -1.48 -> 5).
#     The function returns a dictionary containing:
#     - 'closest_pair_product_of_effective_units': The product of these "effective unit digits"
#       of the closest pair found in the list.
#     - 'original_closest_pair': The actual closest pair of numbers found (as a sorted tuple).
#     - 'list_length': The total number of elements in the input list.
#     - 'sum_of_all_effective_units': The sum of these "effective unit digits" for ALL numbers in the list.
#     - 'average_absolute_value': The average of the absolute values of all numbers.
#     - 'max_value_effective_unit_product_with_min': The product of the "effective unit digit" of the
#       maximum number and the "effective unit digit" of the minimum number in the list.
#     If the input list has fewer than two elements, most statistical values will be None or 0.
#     :param numbers: List[float] - A list of floating-point numbers.
