            if is_valid(nx, ny):
                neighbors.append((nx, ny))
        return neighbors

    def compare_cells(a, b):
        ax, ay = a
        bx, by = b
        av, bv = grid[ax][ay], grid[bx][by]
        ad, bd = get_decimal_part(av), get_decimal_part(bv)
        if av != bv:
            return av - bv
        else:
            return ad - bd

    start_points = [(i, j) for i in range(n) for j in range(n) if grid[i][j] == 1]
    if not start_points:
        return None

    path = []
    for start in start_points:
        current_path = [grid[start[0]][start[1]]]
        current_pos = start
        for _ in range(1, k):
            neighbors = get_neighbors(current_pos[0], current_pos[1])
            if not neighbors:
                break
            next_pos = min(neighbors, key=compare_cells)
            current_path.append(grid[next_pos[0]][next_pos[1]])
            current_pos = next_pos
        if len(current_path) == k:
            if not path or current_path < path:
                path = current_path

    return path if path else None
